SELECT lower(hex(span_id)) AS span FROM tqd_cat.spans AS s WHERE start_ns >= 1790000000000000000 AND start_ns < 1790000060000000000 AND intDiv(start_ns, 300000000000) BETWEEN 5966666 AND 5966666 AND ((multiIf(dynamicType(attrs.`env`) != 'None', NOT (coalesce(attrs.`env`.:String = 'prod', false)), multiIf(has((SELECT groupArray(resource_id) FROM tqd_cat.resources WHERE dynamicType(attrs.`env`) != 'None'), resource_id), has((SELECT groupArray(resource_id) FROM tqd_cat.resources WHERE NOT (coalesce(attrs.`env`.:String = 'prod', false))), resource_id), multiIf(arrayExists(x -> dynamicType(x) != 'None', events.attrs.`env`), NOT (arrayExists(x -> x = 'prod', events.attrs.`env`.:String)), multiIf(arrayExists(x -> dynamicType(x) != 'None', links.attrs.`env`), NOT (arrayExists(x -> x = 'prod', links.attrs.`env`.:String)), multiIf(dynamicType(scope_attrs.`env`) != 'None', NOT (coalesce(scope_attrs.`env`.:String = 'prod', false)), true))))))) ORDER BY span FORMAT TSV
SETTINGS final = 1, json_type_escape_dots_in_keys = 1, max_recursive_cte_evaluation_depth = 10001
